  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']

    # Build node dict and children lists
    node_map = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = {
            'id': nid,
            'parent': n['parent'],
            'symbol': n['symbol'],
            'depth': n['depth'],
            'removable': n['removable'],
            'children': []
        }

    # Build children relationships
    for nid, node in node_map.items():
        pid = node['parent']
        if pid is not None:
            node_map[pid]['children'].append(nid)

    # Initialize symbol count for required symbols
    required_set = set(required_symbols)
    symbol_count = {}
    for n in nodes:
        sym = n['symbol']
        if sym in required_set:
            symbol_count[sym] = symbol_count.get(sym, 0) + 1

    # Check initial feasibility: all required symbols must be present
    for sym in required_set:
        if symbol_count.get(sym, 0) == 0:
            raise ValueError(f"Required symbol '{sym}' not present in tree")

    # Collect removable nodes, sort by depth descending, then id ascending (stable tie break)
    removable_ids = [n['id'] for n in nodes if n['removable']]
    removable_ids.sort(key=lambda x: (-node_map[x]['depth'], x))

    removed = []
    removed_set = set()  # for fast lookup

    for nid in removable_ids:
        node = node_map[nid]
        # Check if node has any children that are not yet removed
        has_retained_child = False
        for cid in node['children']:
            if cid not in removed_set:
                has_retained_child = True
                break
        if has_retained_child:
            continue

        # Check if removing this node would cause any required symbol to disappear
        sym = node['symbol']
        if sym in required_set and symbol_count[sym] == 1:
            continue

        # Remove the node
        removed.append(nid)
        removed_set.add(nid)
        if sym in required_set:
            symbol_count[sym] -= 1

    # Collect retained node ids (all not removed), sorted
    retained = sorted([n['id'] for n in nodes if n['id'] not in removed_set])

    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained
    }"
}
